function paintLines(inst, F, L) {
  inst.svg.style.mixBlendMode = L ? L.blend : '';
  for (const [el] of inst.clips) {
    el.style.strokeWidth = L ? String(2 * L.outline) : '';
    el.style.visibility = L && el.dataset.line === 'none' ? 'hidden' : '';
  }
  for (const [el] of inst.inner) {
    const mode = L ? el.dataset.line || 'stroke' : '';
    el.style.stroke = mode === 'stroke' ? F.ink : '';
    el.style.strokeWidth = mode === 'stroke' ? String(2 * L.stroke) : '';
    el.style.strokeLinejoin = mode === 'stroke' ? 'round' : '';
    el.style.fill = mode === 'ink' ? F.ink : '';
  }
}

// Starts from what is on screen, so reversing mid-way carries on smoothly.
function go(inst) {
  const to = targetOf(inst);
  cancelAnimationFrame(inst.raf);
  if (REDUCED) { inst.cur = to; render(inst); return; }
  const from = inst.cur, t0 = performance.now();
  const tick = (now) => {
    const t = Math.min(1, (now - t0) / DUR);
    inst.cur = interp(from, to, EASE(t));
    render(inst);
    if (t < 1) inst.raf = requestAnimationFrame(tick);
  };
  inst.raf = requestAnimationFrame(tick);
}

// Fantay: takes on the current palette at once, as the page does when its theme flips; a
// motion under way carries on to its end in the new colours.
function recolor(inst) {
  const to = targetOf(inst);
  inst.cur = { ...inst.cur, c: to.c, e: to.e };
  render(inst);
  go(inst);
}

