const SPARK = rp(Array.from({ length: 8 }, (_, i) => {
  const a = -Math.PI / 2 + i * Math.PI / 4, r = i % 2 ? 0.9 : 2.5;
  return [Math.cos(a) * r, Math.sin(a) * r];
}), 0.25);
